\mathsf{IndSat}_{\perp}
=
\{(M,V,X,\operatorname{ind}(\vec t,\vec u,\vec v)):
(M,V,X)\in\mathsf{Team}^{\perp}
\land
\operatorname{FV}(\operatorname{ind}(\vec t,\vec u,\vec v))\subseteq V
\land
\forall s,s'\in X\
(\llbracket\vec t\rrbracket_{M,s}=\llbracket\vec t\rrbracket_{M,s'}
\Rightarrow
\exists s''\in X\
(\llbracket\vec t\rrbracket_{M,s''}=\llbracket\vec t\rrbracket_{M,s}
\land
\llbracket\vec u\rrbracket_{M,s''}=\llbracket\vec u\rrbracket_{M,s}
\land
\llbracket\vec v\rrbracket_{M,s''}=\llbracket\vec v\rrbracket_{M,s'}))\}.
